mapper.delete:
				delete from FIN_CASH_PLAN
				where
				CASH_ID=#{cashId,jdbcType=VARCHAR}

           AND FINPROD_ID = #{finprodId,jdbcType=VARCHAR}


				and BRANCH=#{branch,jdbcType=DECIMAL}


				and MDATE=#{mdate,jdbcType=TIMESTAMP}

mapper.select:
			select  CASH_ID cashId, MDATE mdate, CASH_NUM cashNum, CASH_TYPE cashType, VDATE_UNADJUST vdateUnadjust, 
       MDATE_UNADJUST mdateUnadjust, PAY_DATE_UNADJUST payDateUnadjust, VDATE vdate, 
       PAY_DATE payDate, TERMDAYS termDays, VDATE_Y vdateY, VDATE_TERM vdateTerm, MDATE_TERM mdateTerm, 
       TERMDAYS_TERM termDaysTerm, PRIN_AMT prinAmt, INT_PRIN_AMT intPrinAmt, INT_AMT intAmt, 
       IS_PAY_INT isPayInt, CASH_AMT cashAmt, CASH_BASEAMT cashBaseAmt, CASH_UNIT_TYPE cashUnitType, 
       CALC_FUNCTION calcFunction, FREQUENCY frequence, FINPROD_ID finprodId, FINPROD_TYPE finprodType, 
       FINPROD_TYPE2 finprodType2, BRANCH branch, PAY_TYPE payType, CREATE_USER createUser, 
       CREATE_DEPT createDept, CREATE_TIME createTime, UPDATE_USER updateUser, UPDATE_TIME updateTime
       	from FIN_CASH_PLAN


				and CASH_ID=#{cashId,jdbcType=VARCHAR}


				and FINPROD_ID=#{finprodId,jdbcType=VARCHAR}


				and BRANCH=#{branch,jdbcType=DECIMAL}


				and MDATE=#{mdate,jdbcType=TIMESTAMP}
